import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = 'D:/Repos/angular-jig';
const gate = await import(pathToFileURL(join(ROOT, 'harness/gate/check-responsive.mjs')).href);
const playwright = await import(pathToFileURL(join(ROOT, 'harness/playwright/serve-and-visit.mjs')).href);

const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
const targets = [
  ['dashboard', 'app-dashboard'],
  ['roster', 'app-heroes'],
  ['detail/HRO-0007', 'app-hero-detail'],
  ['missions', 'app-missions'],
  ['threats', 'app-threats'],
  ['recruit', 'app-recruit'],
  ['settings', 'app-settings'],
];

const srv = await playwright.serveStatic(DIST, { spaFallback: true });
const browser = await playwright.launchChromium();
try {
  for (const [route, anchorSelector] of targets) {
    const { failures } = await gate.assertResponsive({
      origin: srv.origin,
      route,
      anchorSelector,
      browser,
    });
    console.log(route, failures.length === 0 ? 'PASS' : 'FAIL ' + JSON.stringify(failures.slice(0, 8)));
  }
} finally {
  await browser.close();
  await srv.close();
}

