const check = (label, ok) => results.push(`${ok ? 'PASS' : 'FAIL'} ${label}`);

try {
  await page.goto(`${srv.origin}/detail/HRO-0007`, { waitUntil: 'networkidle' });
  await page.getByRole('tab', { name: 'Edit' }).click();
  await page.locator('#hero-name').fill('Silverwing Prime');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.getByText('Changes saved.').waitFor({ timeout: 5000 });
  check('detail save shows confirmation', true);

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Dashboard' }).click();
  await page.getByRole('link', { name: 'Silverwing Prime' }).waitFor({ timeout: 5000 });
  check('dashboard roster list shows edited name', true);

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Roster' }).click();
  await page.getByRole('cell', { name: /Silverwing Prime/ }).first().waitFor({ timeout: 5000 });
  check('roster table shows edited name', true);

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Recruit' }).click();
  await page.locator('#recruit-name').fill('Test Recruit');
  await page.locator('#recruit-alias').fill('Unknown');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.getByRole('heading', { name: 'Test Recruit' }).waitFor({ timeout: 5000 });
  const recruitUrl = page.url();
  check(`recruit opens new dossier (${recruitUrl.replace(srv.origin, '')})`, /\/detail\/HRO-0082$/.test(recruitUrl));

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Missions' }).click();
  await page.getByText('Routine deployment').first().waitFor({ timeout: 5000 }).catch(() => {});
  check('missions screen renders', (await page.getByRole('heading', { name: 'Missions' }).count()) > 0);

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Threats' }).click();
  check('threats screen renders', (await page.getByRole('heading', { name: 'Threats' }).count()) > 0);

  await page.getByRole('navigation', { name: 'Primary' }).getByRole('link', { name: 'Settings' }).click();
  check('settings screen renders', (await page.getByRole('heading', { name: 'Settings' }).count()) > 0);

  await page.getByRole('search').getByRole('searchbox').fill('Test');
  await page.getByRole('search').getByRole('searchbox').press('Enter');
  await page.waitForURL(/\/roster\?q=Test/, { timeout: 5000 });
  await page.getByRole('cell', { name: /Test Recruit/ }).first().waitFor({ timeout: 5000 });
  const rows = await page.locator('tbody tr').count();
  check(`topbar search filters roster to matching rows (rows: ${rows})`, rows === 1);
} catch (e) {
  results.push('FAIL flow threw: ' + e.message.split('\n')[0]);
} finally {
  results.forEach((r) => console.log(r));
  console.log(errors.length ? 'runtime errors:\n' + errors.join('\n') : 'no runtime errors');
  await browser.close();
  await srv.close();
}
